#include <stdlib.h>
#include "short.h"

struct shortener {
  uint64_t next_id;
  short_table *by_code;
  short_table *by_url;
};

shortener *shortener_new(void) {
  shortener *s = malloc(sizeof *s);
  if (!s) return NULL;
  s->next_id = 1;
  s->by_code = table_new(64);
  s->by_url = table_new(64);
  if (!s->by_code || !s->by_url) {
    shortener_free(s);
    return NULL;
  }
  return s;
}

void shortener_free(shortener *s) {
  if (!s) return;
  table_free(s->by_code);
  table_free(s->by_url);
  free(s);
}

const char *shortener_add(shortener *s, const char *url) {
  if (!s || !url) return NULL;
  const char *existing = table_get(s->by_url, url);
  if (existing) return existing;
  char code[SHORT_CODE_MAX];
  short_encode(s->next_id, code);
  if (table_set(s->by_code, code, url) != 0 || table_set(s->by_url, url, code) != 0) return NULL;
  s->next_id++;
  return table_get(s->by_url, url);
}

const char *shortener_lookup(const shortener *s, const char *code) {
  if (!s || !code) return NULL;
  return table_get(s->by_code, code);
}

size_t shortener_count(const shortener *s) { return s ? table_len(s->by_url) : 0; }
